import {cipherContent} from './cipher-pages.js';
// SPDX-License-Identifier: GPL-3.0-or-later
const REPO='https://github.com/Fablescateringandevents/v-security-suite';
const mark='<svg viewBox="0 0 64 64" aria-hidden="true"><path d="M6 10h12l14 32 14-32h12L38 56H26z"/><path d="M25 10h14l-7 16z"/></svg>';
const icons={guard:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6z"/><path d="m8 12 3 3 5-6"/>',vault:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 4v3"/>',cipher:'<path d="M3 3h6v6H3zm12 0h6v6h-6zM3 15h6v6H3zm12 0h2v2h-2zm4 0h2v6h-2zm-4 4h2v2h-2z"/>',relay:'<path d="M3 7h17m-5-5 5 5-5 5M21 17H4m5-5-5 5 5 5"/>'};
const icon=name=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+icons[name]+'</svg>';
function layout(title,content,{app=false,cipher=false,indexable=false,canonical='',description='Open-source phone privacy tools. Explore the Vellivex experimental beta, inspect the source and help shape what comes next.'}={}){
return `<!doctype html><html lang="en"${app||cipher?' translate="no"':''}><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0a101b"><meta name="description" content="${description}"><meta name="robots" content="${indexable?'index,follow':'noindex,nofollow'}">${canonical?'<link rel="canonical" href="https://www.vellivex.com'+canonical+'">':''}<title>${title} | Vellivex</title><link rel="icon" href="/icon.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css">${app||cipher?'<link rel="manifest" href="/manifest.webmanifest">':''}<script type="module" src="${cipher?'/cipher-ui.js':app?'/app.js':'/site.js'}"></script></head><body><a href="#main" class="skip">Skip to content</a><header class="site-header"><div class="wrap header-inner"><a class="brand" href="/" aria-label="Vellivex home">${mark}<span class="brand-word">vellivex<small>OPEN SECURITY</small></span></a><button type="button" id="menu-toggle" class="menu-button" aria-expanded="false" aria-controls="navigation">Menu</button><nav id="navigation" aria-label="Main navigation"><a href="/#products">The apps</a><a href="/source">Open source ↗</a><a href="/trust">Our approach</a><a href="/blog">Guides</a><a href="/testing">Start testing</a><a href="/feedback">Feedback</a><a class="button small" href="/beta">Explore the beta <span aria-hidden="true">↗</span></a></nav></div></header><main id="main">${content}</main><footer class="site-footer"><div class="wrap"><div class="footer-top"><a class="brand" href="/">${mark}<span class="brand-word">vellivex<small>OPEN SECURITY</small></span></a><div class="footer-links"><a href="/roadmap">Roadmap</a><a href="/brand">Brand assets</a><a href="/security">Report a vulnerability</a><a href="/privacy">Privacy</a><a href="/terms">Beta information</a><a href="${REPO}">GitHub ↗</a></div></div><div class="footer-bottom"><span>© 2026 Vellivex project. Original code: GPL-3.0-or-later.</span><span>Experimental beta · No independent security audit completed.</span></div></div></footer></body></html>`;
}
function head(eyebrow,title,lead){return `<div class="wrap page-head"><div class="eyebrow"><span class="dot"></span>${eyebrow}</div><h1>${title}</h1><p class="lead">${lead}</p></div>`;}
const appCard=(name,slug,tag,text,action)=>`<article class="product"><div class="product-icon">${icon(slug)}</div><span class="tag ${slug==='guard'?'warn':''}">${tag}</span><h3>${name}</h3><p>${text}</p><a class="text-link" href="/apps/${slug}">${action} <span aria-hidden="true">↗</span></a></article>`;
const experimental='<div class="notice"><strong>Experimental beta.</strong> Use non-sensitive test data. Real-phone validation and independent security review are incomplete. Do not rely on these tools for sensitive communications. <a href="/trust"><u>See what still blocks a wider launch.</u></a></div>';
const products=()=>`<div class="products">${appCard('VGuard','guard','ANDROID · 0.1.3 CANDIDATE','Choose which Android apps can connect. A local firewall with manual profiles and no remote VPN server.','View Android preview')}${appCard('VVault','vault','BROWSER · 0.2.10 BETA','Encrypt and unlock a message locally with a passphrase. Install the files for offline browser use.','Open VVault')}${appCard('VRelay','relay','BROWSER · 0.2.10 BETA','Copy, save or share an encrypted VVault package. Keep the passphrase on a separate channel.','Open VRelay')}${appCard('V Cipher','cipher','TWO-PHONE · 0.1.9 RESEARCH','Offline identity keys and signed, doubly encrypted messages. Numbered QR frames connect Vault and Relay devices.','Explore V Cipher')}</div>`;
function home(){return layout('Privacy, on your terms.',`<div class="wrap"><section class="hero"><div><div class="eyebrow"><span class="dot"></span>VELLIVEX / OPEN-SOURCE PHONE PRIVACY</div><h1>Privacy,<br><em>on your terms.</em></h1><p class="lead">Your phone holds your world. Choose what connects, keep messages private, and inspect the code behind every tool. Welcome to Vellivex.</p><div class="actions"><a class="button" href="/beta">Explore the free beta <span aria-hidden="true">↗</span></a><a class="button secondary" href="/source">Inspect the source <span aria-hidden="true">↗</span></a></div><p class="fine">Testing release only. Wider launch is blocked pending device validation and security review.<br>Free during beta. No card. No advertising trackers.</p></div><div class="device-stage" aria-label="Illustration of the VGuard interface"><div class="phone"><div class="phone-top"><span>9:41</span><span>▰ ▰</span></div><div class="camera"></div><div class="phone-title">vellivex <span>VGUARD</span></div><div class="shield-large brand-emblem">${mark}</div><div class="phone-heading">Choose what connects.</div><p class="phone-caption">You set the boundaries.<br>VGuard applies your selected rules.</p><div class="phone-rule"><span class="app-glyph">A</span><div>Example app<small>Network access blocked</small></div><span class="toggle"></span></div><div class="phone-rule"><span class="app-glyph">B</span><div>Another app<small>Network access allowed</small></div><span class="muted">↗</span></div><div class="phone-caption">NORMAL PROFILE · LOCAL FILTERING</div></div><div class="floating-label"><span class="dot"></span> YOUR PHONE. YOUR BOUNDARIES.</div><div class="device-label">Product illustration · not a live device reading</div></div></section><div class="principles"><div><span>⌘</span> Source you can inspect</div><div><span>◇</span> Local processing in our browser tools</div><div><span>↗</span> Honest about what is still untested</div></div><section id="products" class="section"><div class="section-heading"><div><p class="eyebrow">01 / THE TOOLKIT</p><h2>Four tools.<br>A clearer sense of control.</h2></div><p>Start with the tool you need. Each has a defined purpose, visible source and a published beta status.</p></div>${products()}</section><section class="section split border-top"><div><p class="eyebrow">02 / TRUST THROUGH TRANSPARENCY</p><h2>Security deserves<br>more than a promise.</h2><p>Read the code. Read the test results. Read the limits. We want people to question our work and help improve it.</p><div class="source-panel"><div class="label">VELLIVEX / PUBLIC SOURCE</div><div><span class="green">apps/</span><br>├ vguard/ <span class="comment"># native Android firewall</span><br>├ vault/ <span class="comment"># local message encryption</span><br>└ relay/ <span class="comment"># encrypted-package transfer</span><br><span class="green">LICENSE</span> <span class="comment"># GPL-3.0-or-later</span><br><span class="green">SECURITY.md</span> <span class="comment"># disclosure & limitations</span></div></div><div class="actions"><a class="text-link" href="/source">Explore the public project ↗</a></div></div><ol class="feature-list"><li><span class="num">01</span><div><h3>Defined boundaries</h3><p>VGuard filters selected app connections. VVault encrypts messages. Neither is a universal spyware detector.</p></div></li><li><span class="num">02</span><div><h3>Your data stays in your workflow</h3><p>VVault and VRelay process messages in your browser. Their code does not upload message contents or passphrases.</p></div></li><li><span class="num">03</span><div><h3>Evidence before claims</h3><p>Automated checks are published separately from real-phone tests. Independent review is a gate for a wider launch.</p></div></li></ol></section><section class="section border-top"><div class="beta-banner"><div><p class="eyebrow">03 / HELP SHAPE WHAT COMES NEXT</p><h2>Start small. Make it stronger.</h2><p>We are quietly opening an experimental beta. Try it with test data, tell us where it falls short, and help set the priorities.</p></div><a class="button" href="/beta">See the beta details ↗</a></div></section></div>`);}
function beta(){return layout('The small beta',head('EARLY ACCESS / FREE DURING BETA','Start small.<br><em>Help us get it right.</em>','Explore the early tools, understand their limits and tell us what should change before a wider launch.')+`<div class="wrap content">${experimental}${products()}<section class="section split"><div><h2>A clear path from<br>beta to launch.</h2><p>We are starting with a quiet, unindexed release. There is no paid subscription or automatic charge in this beta.</p><a class="button secondary" href="/feedback">Send private feedback ↗</a></div><div><div class="release-step"><span class="num">01</span><div><h3>Try with test data</h3><p>Use a spare device for VGuard and non-sensitive messages for VVault. Follow the published test instructions.</p></div></div><div class="release-step"><span class="num">02</span><div><h3>Report what actually happened</h3><p>Include the tool, phone OS, expected behaviour and result. Remove passwords, personal information and message contents.</p></div></div><div class="release-step"><span class="num">03</span><div><h3>Fix, retest, then expand</h3><p>Review feedback, correct defects and complete real-phone and independent security checks before a wider release.</p></div></div></div></section><h2>The future paid offer</h2><div class="proposed"><div class="panel"><p class="mini-heading">NOW / EXPERIMENTAL BETA</p><div class="price">Free</div><p>Explore the previews and published source. No payment details collected.</p></div><div class="panel"><p class="mini-heading">LATER / PROPOSAL ONLY</p><div class="price">£4.99 <small>/ month</small></div><p>Or £39.99/year, subject to cost and feature validation. A free introduction followed by an explicit subscription choice. Paid services are not available yet.</p></div></div><p class="fine">Open-source rights continue regardless of subscription. The final paid service must earn its place through maintained services and support.</p></div>`);}
function vault(){return layout('VVault — local message encryption',head('VVAULT / 0.2.10 BETA','Keep the message<br><em>in your hands.</em>','Encrypt or unlock a text message locally in your browser. Keep the encrypted package and its passphrase separate.')+`<div class="wrap content">${experimental}<div class="app-layout"><section class="panel"><form id="vault-form"><label class="field"><span>What would you like to do?</span><select id="vault-mode"><option value="encrypt">Encrypt a message</option><option value="decrypt">Unlock an encrypted package</option></select></label><label class="field"><span id="message-label">Your message</span><textarea id="message" data-sensitive required maxlength="180000" placeholder="Use a non-sensitive test message during beta." spellcheck="false" autocorrect="off" autocapitalize="off" autocomplete="off" translate="no" writingsuggestions="false"></textarea><small>Messages up to 128 KiB. Nothing is uploaded by this tool.</small></label><label class="field"><span>Passphrase</span><input type="password" id="passphrase" data-sensitive required maxlength="1024" spellcheck="false" autocorrect="off" autocapitalize="off" autocomplete="off" translate="no" writingsuggestions="false"><small>For new messages, use at least 14 characters. Four or more random words are better than a predictable phrase.</small></label><label id="confirm-wrap" class="field"><span>Confirm passphrase</span><input id="passphrase-confirm" type="password" data-sensitive required maxlength="1024" spellcheck="false" autocorrect="off" autocapitalize="off" autocomplete="off" translate="no" writingsuggestions="false"></label><div class="app-actions"><button id="vault-submit" class="button" type="submit">Encrypt on this device</button><button id="clear-session" class="button secondary" type="button">Clear session</button></div></form><p id="app-status" class="status" role="status" aria-live="polite">Ready. Use non-sensitive test messages during this beta.</p><div class="result-area"><label class="field"><span id="result-label">Result</span><textarea readonly id="result" class="mono" data-sensitive aria-label="Result" spellcheck="false" autocorrect="off" autocapitalize="off" autocomplete="off" translate="no" writingsuggestions="false"></textarea></label><div class="app-actions"><button id="copy-result" class="button secondary" type="button">Copy result</button><button id="download-result" class="button secondary" type="button" hidden>Save encrypted file</button></div></div></section><aside class="panel sidebar"><h3>Automatic session lock.</h3><p>Leaving this tab or two minutes without input clears your session. Save encrypted results before leaving. Clearing this page does not clear your clipboard.</p><h3>Offline by choice.</h3><p>Install the tool files, disconnect Wi-Fi and mobile data, then reload to verify offline use on your device. If files are missing, save encrypted downloads, close tool tabs, clear this site’s stored data in browser settings, then reopen online and install again.</p><button id="offline-enable" class="button secondary small" type="button">Enable offline use</button><h3>How this beta works</h3><ul><li>AES-256-GCM authenticated encryption.</li><li>PBKDF2-SHA256 with 600,000 iterations and a random salt.</li><li>Fresh encryption nonce for each message.</li><li>No account, message history or recovery service.</li></ul><p>A forgotten passphrase cannot be recovered. This is passphrase-based encryption, without sender verification or forward secrecy. It cannot protect a compromised device.</p><p>Browser memory and clipboard contents cannot be guaranteed to be securely erased. Reloading an online page may load changed code; review and run the source offline for a stronger separation.</p><div class="row-links"><a class="text-link" href="/apps/relay">Open VRelay ↗</a><a class="text-link" href="/source">Read the code ↗</a></div></aside></div></div>`,{app:true});}
function relay(){return layout('VRelay — encrypted-package transfer',head('VRELAY / 0.2.10 BETA','Move the package.<br><em>Keep the key apart.</em>','Load an encrypted VVault package, check its format, then copy, save or share it through a channel you choose.')+`<div class="wrap content">${experimental}<div class="app-layout"><section class="panel"><form id="relay-form"><label class="field"><span>Load a .vvault file (optional)</span><input type="file" id="relay-file" accept=".vvault,.json,application/json"><small>The selected file is read on this device.</small></label><label class="field"><span>Encrypted VVault package</span><textarea id="relay-package" class="mono" required maxlength="200000" data-sensitive placeholder="Paste the encrypted JSON package from VVault." spellcheck="false" autocorrect="off" autocapitalize="off" autocomplete="off" translate="no" writingsuggestions="false"></textarea></label><div class="app-actions"><button class="button" type="submit">Check package format</button><button id="clear-session" class="button secondary" type="button">Clear session</button></div></form><p id="app-status" class="status" role="status" aria-live="polite">Ready. VRelay never asks for a passphrase.</p><div class="result-area"><label class="field"><span>Package ready to transfer</span><textarea id="result" readonly class="mono" data-sensitive spellcheck="false" autocorrect="off" autocapitalize="off" autocomplete="off" translate="no" writingsuggestions="false"></textarea></label><div class="app-actions"><button id="copy-result" type="button" class="button secondary">Copy package</button><button id="download-package" type="button" class="button secondary" disabled>Save file</button><button id="share-package" type="button" class="button" disabled>Share package</button></div></div></section><aside class="panel sidebar"><h3>Automatic session lock.</h3><p>Leaving this tab or two minutes without input clears the package from the page. Save or copy it first.</p><h3>Transfer without unlocking.</h3><p>VRelay checks the envelope structure. It does not decrypt, authenticate the sender or prove the contents are safe.</p><p>There is no hosted relay or delivery tracking in this version. Your chosen messaging or sharing app controls delivery and can see the encrypted package and its metadata.</p><p>Send the passphrase separately. Never place it beside the package on this page.</p><button id="offline-enable" class="button secondary small" type="button">Enable offline use</button><p class="fine">After installation, disconnect your networks and reload to verify offline access.</p><a href="/apps/vault" class="text-link">Open VVault ↗</a></aside></div></div>`,{app:true});}
function guard(){return layout('VGuard — Android firewall preview',head('VGUARD / ANDROID 10+ / 0.1.3 CANDIDATE','Choose which apps<br><em>can connect.</em>','A native Android local-VPN firewall. Select apps to block while other apps keep their normal connection.')+`<div class="wrap narrow content"><div class="notice"><strong>Developer preview: live blocking is unverified.</strong> This candidate restricts CSV exports to explicitly granted document destinations and retains two startup race fixes and has been rebuilt and signature-checked. It has not yet been run on an Android phone. Automated test passes do not demonstrate real-phone protection. Use a spare test device and do not rely on this preview for sensitive activity.</div><div class="download-box"><p class="mini-heading">ANDROID CANDIDATE / 90,718 BYTES</p><h3>VGuard 0.1.3</h3><p>Manual Normal and Journey profiles, selected-app blocking, packet metadata and CSV export. No account or remote VPN server.</p><div class="actions"><a class="button" href="/downloads/VGuard-0.1.3-candidate.apk" download>Download experimental APK ↓</a><a class="button secondary" href="/downloads/VGuard-Source-GPL.zip" download>Download source ↓</a></div><p class="hash">APK SHA-256: 6977d17d356f76a181a4979bf4fefa4f486167b90e2df612e5c93aed4977df58</p></div><h2>What this candidate changes</h2><p>CSV exports reject file URIs, missing or revoked write grants and invalid document destinations before opening a stream. Startup also rejects VPN revocation and changed Android app identities before publishing an active session. New regression checks reproduce both earlier races. These host checks do not establish Android routing behaviour.</p><p><a href="/downloads/VGuard-0.1.3-Security-Notes.txt"><u>Read the candidate security notes</u></a> · <a href="/downloads/SHA256SUMS.txt"><u>Release checksums</u></a></p><h2>What this preview does</h2><ul><li>Routes selected apps into a local VPN interface and discards their packets.</li><li>Offers manually selected Normal and Journey profiles.</li><li>Shows discarded-packet counts and recent destination metadata.</li><li>Contains no account, analytics or INTERNET permission.</li><li>Candidate privacy controls prevent ordinary screenshots and exclude app data from Android backup and transfer.</li></ul><h2>Know its boundaries</h2><ul><li>Blocking can end when Android ends the process, VPN consent is revoked, rules fail or you stop the service.</li><li>No always-on mode, lockdown, automatic restart or automatic car detection.</li><li>Uses Android’s VPN slot and can replace another VPN.</li><li>Does not control microphone, camera or location permissions, detect all spyware or interfere with external trackers.</li><li>A blocked app may store information and send it after its connection is restored.</li></ul><h2>The first real-phone test</h2><ol><li>With VGuard off, confirm two independent test apps can make fresh network requests.</li><li>Select only one app in VGuard. Start blocking and approve Android’s VPN request.</li><li>Check that the selected app fails to connect while the other app still connects.</li><li>Stop blocking and confirm the selected app can connect again.</li></ol><p>That comparison is only the first gate. IPv6, DNS, bypass attempts, sleep, network changes, upgrades and battery behaviour still need testing.</p><div class="actions"><a class="button secondary" href="/downloads/VGuard-Setup.txt">Setup guide ↗</a><a class="button secondary" href="/downloads/VGuard-Test-Report.txt">Earlier test report ↗</a><a class="button" href="/feedback?product=VGuard">Report your result ↗</a></div></div>`);}
function feedbackPage(security=false){return layout(security?'Private vulnerability report':'Share beta feedback',head(security?'SECURITY / PRIVATE REPORT':'BETA / PRIVATE FEEDBACK',security?'Help us fix it.<br><em>Report it privately.</em>':'What worked?<br><em>What needs to change?</em>',security?'Tell us which product is affected and how to reproduce the issue with a harmless test case. Never send real secrets or other people’s information.':'Useful feedback starts with the tool you tried, what you expected and what actually happened.')+`<div class="wrap narrow content"><div class="notice">This form saves your report privately for the project owner. Do not include passwords, encryption keys, message contents, personal details or sensitive logs. We are not collecting contact details in this beta.</div><form id="feedback-form" class="panel"><div class="fields-two"><label class="field"><span>Product</span><select name="product" required><option value="VGuard">VGuard</option><option value="VVault">VVault</option><option value="VRelay">VRelay</option><option value="VCipher">V Cipher</option><option value="Website">Website</option></select></label><label class="field"><span>Report type</span><select name="kind" required>${security?'<option value="security">Security issue</option>':'<option value="bug">Bug or unexpected behaviour</option><option value="idea">Improvement idea</option><option value="test">Device test result</option><option value="security">Security issue (private)</option><option value="deletion">Delete an earlier report</option>'}</select></label></div><label class="field"><span>Device operating system</span><select name="os" required><option value="Android">Android</option><option value="iPhone/iPad">iPhone / iPad</option><option value="Desktop">Desktop browser</option><option value="Other">Other / not applicable</option></select></label><label class="field"><span>${security?'Issue and safe reproduction steps':'Your feedback'}</span><textarea name="message" required minlength="20" maxlength="3000" placeholder="Tool version and OS version; expected result; actual result; steps to reproduce. Use test data only."></textarea><small>20–3,000 characters. For deletion, include the reference shown after your original submission.</small></label><label class="honeypot" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><label class="check"><input type="checkbox" name="safe" required><span>I have removed passwords, keys, personal details and sensitive content. I understand this report is saved privately as described in the <a href="/privacy"><u>privacy information</u></a>.</span></label><button id="feedback-submit" class="button" type="submit">Send private report ↗</button><p id="feedback-status" class="status" role="status" aria-live="polite"></p></form><p class="fine">This is a project feedback route, without a guaranteed response time or emergency monitoring. Public feature discussions can also go to <a href="${REPO}/issues"><u>GitHub Issues</u></a>. Keep vulnerability details private until a fix is available.</p></div>`);}
function source(){return layout('Open source',head('PUBLIC CODE / GPL-3.0-OR-LATER','Inspect it.<br><em>Question it. Improve it.</em>','The source for the native Android candidate, browser tools and beta website is published together. No private signing keys are included.')+`<div class="wrap narrow content"><div class="actions"><a class="button" href="${REPO}">Open the GitHub repository ↗</a><a class="button secondary" href="/downloads/V-Security-Source.zip" download>Download source archive ↓</a></div><h2>What is included</h2><table><thead><tr><th>Component</th><th>Source</th><th>Status</th></tr></thead><tbody><tr><td>VGuard</td><td><code>apps/vguard/</code></td><td>Android 0.1.3 candidate; real-phone enforcement unverified</td></tr><tr><td>VVault</td><td><code>apps/vault/</code>, <code>web/app.js</code></td><td>Browser beta with local Web Crypto</td></tr><tr><td>VRelay</td><td><code>web/app.js</code></td><td>Browser beta; manual transfer only</td></tr><tr><td>V Cipher</td><td><code>apps/cipher/</code>, <code>web/cipher-ui.js</code></td><td>Research build; physical two-phone tests and independent protocol review outstanding</td></tr><tr><td>Website / feedback</td><td><code>server/</code>, <code>web/</code></td><td>Experimental website and private feedback storage</td></tr></tbody></table><h2>Free to inspect and adapt</h2><p>Original project code is licensed under GPL-3.0-or-later. You can use, study, modify and redistribute it under that licence. The complete licence is included with the source. Open-source rights do not depend on buying a future subscription.</p><p>Private signing materials and operational feedback records are excluded. Unsigned VGuard payload reproduction is documented in the public source. Byte-identical signed APK containers and independent auditing are not claimed.</p><h2>Contribute with evidence</h2><p>Open an issue with a non-sensitive test case or propose a focused pull request. Include the relevant version, phone OS and observed behaviour. Security issues belong in the <a href="/security"><u>private reporting form</u></a>.</p><div class="actions"><a href="${REPO}/issues" class="button secondary">Open an issue ↗</a><a href="/downloads/RELEASE-NOTES.txt" class="button secondary">Read release notes ↗</a></div></div>`);}
function trust(){return layout('Our security approach',head('OUR APPROACH / EVIDENCE FIRST','Trust is earned.<br><em>In the details.</em>','Defined capabilities, published limitations and testing that separates what passed from what has not been verified.')+`<div class="wrap narrow content"><h2>A small, defined scope</h2><p>VGuard controls selected Android app connections. VVault uses passphrase-based message encryption. VRelay handles encrypted packages. We are not promising complete device security, spyware detection or protection from every attacker.</p><h2>Wider launch remains blocked</h2><p>The public site is an evaluation beta. Passing automated checks does not authorise a production launch or establish that a tool is unhackable.</p><table><thead><tr><th>Tool</th><th>Open launch gate</th></tr></thead><tbody><tr><td>VGuard</td><td>Real Android block, leak and lifecycle testing. Blocking ends when its VPN service stops; always-on and lockdown are not implemented.</td></tr><tr><td>VVault / VRelay</td><td>Android and iPhone offline, import, sharing and sensitive-session tests; independent review.</td></tr><tr><td>V Cipher</td><td>Physical two-phone camera and isolation tests, independent protocol review and acceptance of its lack of forward secrecy and session-only replay records.</td></tr><tr><td>Website</td><td>Operational feedback handling and hosting/access review. Automated input and storage tests do not establish resistance to every attack or distributed load.</td></tr></tbody></table><p><a href="https://github.com/Fablescateringandevents/v-security-suite/blob/main/docs/ACCEPTANCE.md"><u>Read the acceptance gates and required evidence.</u></a></p><h2>Current evidence</h2><p>The 0.5.2 internal review passed 243 automated tests across the suite and validated the assembled website and offline file hashes. Free remote mobile testing reproduced an older-Chrome compatibility failure; the release removes those newer JavaScript dependencies. Temporary encoded plaintext is also cleared on oversize or secure-randomness failure. Form text is now at least 16 pixels; the Safari focus-zoom observation still needs a mobile retest. Virtual-device checks are partial and do not replace the physical-device gates. <a href="https://github.com/Fablescateringandevents/v-security-suite/blob/main/docs/REMOTE-MOBILE-TESTING-2026-10-24.md"><u>Read the reproduced findings, fixes and verification limits.</u></a></p><table><thead><tr><th>Area</th><th>What we can say</th></tr></thead><tbody><tr><td>VGuard automated logic</td><td>Existing core, adversarial-engine and CSV checks rerun successfully on 23 October 2026. They use host code and controlled Android stubs.</td></tr><tr><td>VGuard Android behaviour</td><td>The 0.1.3 candidate is compiled and signature-checked. Usable app launch and live routing remain unverified.</td></tr><tr><td>Browser encryption</td><td>Automated round-trip, tamper rejection, malformed-input and wrong-passphrase checks. Device/browser testing is tracked separately.</td></tr><tr><td>Independent audit</td><td>Not completed.</td></tr><tr><td>VGuard payload reproduction</td><td>All eight compiled payload entries match a clean unsigned rebuild with the documented toolchain. Byte-identical signed APK containers and arbitrary-toolchain reproducibility are not claimed.</td></tr></tbody></table><h2>Local tools, transparent hosting</h2><p>The browser app code has no message-upload operation, analytics SDK or third-party script. Encrypted packages and passphrases are processed locally. The website host still receives ordinary web requests and may process infrastructure logs. The encryption and transfer pages block app-initiated network connections using a page security policy. Optional offline installation downloads a release-specific set of tool files, checks their hashes and restores their pinned security headers. Once controlled by that offline worker, missing files produce an error instead of silently loading replacement code. The optional feedback form sends only the report you submit.</p><h2>Protection should be understandable</h2><p>No invented threat counters, unverified “military-grade” claims or promise that a device is unhackable. Vellivex pairs a clear visual identity with published evidence; the branding makes no claim of certification.</p><div class="actions"><a class="button" href="/source">Review the source ↗</a><a class="button secondary" href="/security">Report a vulnerability ↗</a></div></div>`);}
function roadmap(){return layout('Release roadmap',head('THE ROADMAP / SMALL TO WIDE','Build. Listen.<br><em>Improve. Expand.</em>','A wider launch depends on evidence and feedback. These stages describe gates, rather than promised dates.')+`<div class="wrap narrow content">${[['01','Small experimental beta','Website, public code, browser tools, existing Android preview and private feedback. Quiet release with search indexing disabled.','CURRENT'],['02','Improve with real device results','Reproduce reports, fix defects, verify Android block/restore and lifecycle behaviour, and test browser tools on real phones.','NEXT'],['03','Independent review and paid pilot','Complete security review, address findings, validate costs and implement an explicitly accepted free introduction and paid subscription.','PLANNED'],['04','Wider launch','Publish validated releases, prepare supported app-store distribution and marketing, and expand only after acceptance gates pass.','LATER']].map(([num,title,text,tag])=>`<div class="release-step"><span class="num">${num}</span><div><h3>${title}</h3><p>${text}</p></div><span class="tag">${tag}</span></div>`).join('')}<h2>Further products</h2><p>VPhone, VDecoy and VShield are outside this small beta. They need separate capability validation and release work before inclusion.</p><a class="button" href="/feedback">Help set the priorities ↗</a></div>`);}
function privacy(){return layout('Privacy information',head('PRIVACY / BETA INFORMATION','Know what<br><em>leaves your device.</em>','Updated 23 October 2026. This page describes the current experimental beta.')+`<div class="wrap narrow content"><h2>Messages and passphrases</h2><p>VVault encrypts and decrypts locally using the browser’s Web Crypto API. VRelay reads encrypted packages locally. Our app code does not send message contents, passphrases or imported package files to the website server. Neither tool stores message history in local storage or its offline cache. The session clears when the tab is hidden, on page exit, on return from browser history, or after two minutes without input. A successful encryption also clears its original plaintext draft. This reduces exposure but cannot guarantee erasure from browser or operating-system memory.</p><h2>V Cipher two-device research build</h2><p>V Cipher adds a separate offline Vault and online Relay workflow. Identity keys, backup passphrases, conversation secrets and plaintext are handled locally on the Vault role. Its browser-offline and confirmation checks do not prove physical isolation. Camera scanning starts only after your request; frames are decoded locally and our app code does not upload them. Camera tracks stop on lock, hide and page exit. Encrypted identity backups are downloaded only at your request. Replay records are kept only in the unlocked session and reset on lock/reload. QR dependencies are bundled locally, without a CDN.</p><h2>Keyboard and browser assistance</h2><p>Tool pages ask browsers to disable spelling, automatic correction, writing suggestions and translation for sensitive fields. These settings are hints, not an isolation boundary. Your keyboard, browser extensions, translation services or operating system may still read input. Use an offline keyboard and disable cloud text services when testing; the site cannot enforce that choice.</p><h2>Offline files and clipboard</h2><p>“Enable offline use” saves the tool’s public code and interface files in your browser’s service-worker cache. It does not intentionally save your messages. Explicit copies and downloads create separate clipboard entries or files, which you control. Other software may retain copies. Clearing a page cannot guarantee secure memory erasure.</p><h2>Website hosting</h2><p>Serving the website necessarily exposes network information such as your IP address, request URL and browser headers to the hosting infrastructure. The project adds no advertising trackers or analytics cookies. Infrastructure processing is separate from the local encryption operation.</p><h2>Optional feedback</h2><p>The private report form sends your chosen product, report type, device category and report text to the project owner. It does not request your name or email. A daily network pseudonym, computed using HMAC with a private server key, is stored for abuse prevention; it is not a guarantee of anonymity. Report text can itself identify someone, so remove personal details before submitting.</p><p>Only the project owner can read stored reports through the hosting administration tools. There is no public report-list endpoint. Reports are reviewed for fixes and deletion; no automatic deletion schedule or guaranteed response time is claimed. To request deletion, use the form’s deletion option and include your report reference.</p><h2>External links and sharing</h2><p>GitHub and any messaging app you select have their own privacy practices. Sharing an encrypted package discloses that package and metadata to the chosen service. Never send its passphrase alongside it.</p><a class="button secondary" href="/feedback">Contact the project privately ↗</a></div>`);}
function terms(){return layout('Beta information',head('PARTICIPATION / EXPERIMENTAL TOOLS','A beta with<br><em>clear boundaries.</em>','Please understand the current status before you test a tool.')+`<div class="wrap narrow content"><h2>Use test data and test devices</h2><p>This release is for evaluation and feedback. It has not completed real-phone validation or independent security review. Avoid sensitive messages and do not rely on it as your primary protection. Keep a separate backup of information you cannot afford to lose.</p><h2>No payment in this beta</h2><p>No payment details are collected and no subscription is activated. Future plans, features and illustrative prices are proposals. A paid service would need a separate, clear purchase flow and published terms before charging.</p><h2>Open-source licence</h2><p>The included original source is available under GPL-3.0-or-later, including its warranty provisions. See the full licence in the repository. This beta information does not remove rights you have under applicable law.</p><h2>What happens next</h2><p>We will use reported defects and device results to set the next changes. There is no promised launch date or guarantee that every proposed feature will ship. Version changes and known limitations will be documented.</p><a class="button" href="/beta">Choose a tool ↗</a></div>`);}
function brandPage(){return layout('Vellivex brand assets',head('VELLIVEX / IDENTITY','A mark of<br><em>our own.</em>','Our geometric V combines two open wings and an inner facet. A simple, scalable identity for the Vellivex family.')+`<div class="wrap narrow content"><div class="brand-preview"><img src="/brand/vellivex-logo.svg" alt="Vellivex — open security" width="280" height="92"></div><div class="actions"><a class="button" href="/brand/vellivex-logo.svg" download>Logo for dark backgrounds ↓</a><a class="button secondary" href="/brand/vellivex-logo-dark.svg" download>Logo for light backgrounds ↓</a><a class="button secondary" href="/brand/vellivex-mark.svg" download>Vellivex symbol ↓</a></div><h2>Open security.</h2><p>VGuard, VVault, VRelay and V Cipher are part of Vellivex. These marks identify the project; they do not represent independent certification or a guarantee of protection.</p><div class="brand-swatches"><div><span class="swatch-ice"></span><b>Ice</b><code>#A5E5ED</code></div><div><span class="swatch-ink"></span><b>Ink</b><code>#0A101B</code></div><div><span class="swatch-paper"></span><b>Paper</b><code>#F3F6FB</code></div></div></div>`);}
function cipherPage(role){return layout('V Cipher — '+(role==='vault'?'offline Vault':role==='relay'?'online Relay':'two-phone QR messages'),head('V CIPHER / 0.1.9 RESEARCH',role==='vault'?'Your offline<br><em>Vault.</em>':role==='relay'?'Carry ciphertext.<br><em>Keep secrets apart.</em>':'Two devices.<br><em>One private conversation.</em>','A recovered experimental project, continued with bounded QR transfer. Use synthetic data; physical two-phone operation is unverified.')+cipherContent(role),{cipher:Boolean(role)});}
export function page(path){if(path==='/testing')return testingPage();if(path==='/blog')return blogIndex();if(path.startsWith('/blog/'))return blogArticle(path.slice(6));return ({'/apps/cipher':()=>cipherPage(),'/apps/cipher/vault':()=>cipherPage('vault'),'/apps/cipher/relay':()=>cipherPage('relay'),'/':home,'/beta':beta,'/apps/vault':vault,'/apps/relay':relay,'/apps/guard':guard,'/feedback':()=>feedbackPage(false),'/security':()=>feedbackPage(true),'/source':source,'/trust':trust,'/brand':brandPage,'/roadmap':roadmap,'/privacy':privacy,'/terms':terms})[path]?.();}
export function notFound(){return layout('Page not found',head('404 / PAGE NOT FOUND','Let’s get you<br><em>back on track.</em>','This page is not part of the current beta.')+'<div class="wrap content"><a class="button" href="/">Back to Vellivex ↗</a></div>');}

const blogPosts=[{"slug": "technical-vvault-envelope-design", "title": "Inside VVault: passphrase encryption and strict envelope parsing", "desc": "The VVAULT version 1 format, PBKDF2 derivation, AES-GCM authentication and the security boundaries that remain outside the envelope.", "tag": "Technical write-up · Cryptography", "body": "<p>By V · 23 October 2026. This is an implementation note for the experimental VVAULT version 1 format, reviewed in the VVault 0.2.9 source. It is not a new cryptographic protocol recommendation or an independent security assessment. Use synthetic data only.</p><h2>From text to an authenticated package</h2><p>VVault encodes the message as UTF-8 and generates a fresh 16-byte salt and 12-byte IV using browser Web Crypto. PBKDF2 with SHA-256 and 600,000 iterations derives a non-extractable 256-bit AES key from the passphrase and salt. AES-GCM encrypts the message with a 128-bit authentication tag.</p><p>The additional authenticated data is the fixed string <code>VVAULT:1:PBKDF2-SHA256:600000:AES-256-GCM</code>. It binds this operation to the expected format and algorithm suite. The salt and IV are public parameters, not secrets. Their presence in the package is intentional.</p><h2>The envelope contract</h2><p>The JSON package has exactly eight members: <code>format</code>, <code>version</code>, <code>kdf</code>, <code>iterations</code>, <code>cipher</code>, <code>salt</code>, <code>iv</code> and <code>ciphertext</code>. Algorithm identifiers and iteration count must match the supported constants; the parser does not accept arbitrary caller-selected parameters.</p><p>Input is bounded to 200,000 JavaScript string characters. Decoded plaintext is capped at 128 KiB of UTF-8 bytes. Salt and IV lengths are checked, and binary fields must have canonical base64 spelling. Duplicate top-level JSON names, including escaped equivalents, are refused so different parsers cannot silently select different values.</p><h2>Wrong password and altered data</h2><p>The decrypt operation validates the package before deriving the key. AES-GCM authentication failure produces one message: the passphrase is wrong or the package changed. The interface does not claim it can reliably distinguish those causes. Successful output uses strict UTF-8 decoding and preserves an authenticated leading Unicode marker.</p><h2>What the passphrase requirement means</h2><p>Encryption requires at least 14 JavaScript string characters and accepts at most 1,024. Length is not entropy: a predictable long phrase can still be guessed. PBKDF2 adds work to each attempt but does not turn a weak passphrase into a strong one. A captured package supports offline guessing; there is no server-side login limit to protect it.</p><h2>Limits of the construction</h2><p>Knowing the shared passphrase permits creating a valid package, so authentication of ciphertext integrity is not authentication of a particular person. VVault has no sender identity, recovery or forward secrecy. A compromised browser or origin can defeat the workflow. The implementation wipes owned byte buffers where practical, but cannot guarantee removal of JavaScript strings or OS/browser copies.</p><h2>Review and reproduce</h2><p>Inspect the encryption and parser code, then run the repository’s Node tests against a recorded revision. A passing suite covers its cases; it does not prove the absence of other flaws. See the source links below and report sensitive findings privately through <a href=\"/security\">the reporting route</a>.</p><p><a href=\"https://github.com/Fablescateringandevents/v-security-suite/blob/main/apps/vault/crypto.js\">Encryption and envelope source</a> · <a href=\"https://github.com/Fablescateringandevents/v-security-suite/blob/main/tests/crypto.test.mjs\">Crypto regression tests</a></p>"}, {"slug": "technical-offline-integrity-and-response-policy", "title": "Offline integrity: verifying bytes is only half the response", "desc": "How Vellivex pins offline asset hashes and response policy, handles corrupt caches and defines the trusted-origin boundary.", "tag": "Technical write-up · Browser security", "body": "<p>By V · 23 October 2026. This note describes the reviewed VVault/VRelay 0.2.9 offline implementation. It explains a bounded integrity mechanism, not a guarantee that a browser application is safe to use for sensitive communications.</p><h2>A response has bytes and policy</h2><p>A browser’s interpretation of a file depends on more than its body. Content type, Content Security Policy, permissions and isolation headers influence how code executes. A correct body hash does not authenticate arbitrary cached response headers.</p><h2>Build a canonical manifest</h2><p>The build asks the same route handler used for live delivery for each offline asset’s canonical response. It records the SHA-256 integrity value and canonical headers. The offline release identity hashes the manifest and service-worker template, so changes to either generate a different cache identity.</p><h2>Verify, then reconstruct</h2><p>The service worker’s <code>verifiedResponse</code> requires a complete policy map, reads the response bytes and compares their SHA-256 digest with the manifest. It then constructs a new status-200 response using those bytes and release-pinned headers. It does not return the mutable cached response object.</p><p>This discards unsolicited cached metadata such as redirect or download headers. Required policy fields include content type, CSP, permissions policy, referrer policy, isolation headers and cache control. Installation verifies responses before storing them. Every intercepted offline read verifies again to detect later corruption.</p><h2>Fail closed, with recovery instructions</h2><p>Missing files, mismatched digests or incomplete policy metadata produce a 503 response with recovery guidance. The tool does not silently substitute an unverified network response for an intercepted offline asset. A failed new installation removes that new cache; a repeated installation of an existing release verifies rather than rewriting its files.</p><h2>The boundary this does not cross</h2><p>The manifest and service worker are delivered by the origin. An attacker controlling that origin may serve a malicious worker and matching manifest. Hashes do not independently establish who wrote the code or whether it is safe. Offline installation also does not establish physical network isolation, a trustworthy OS, or an absence of browser extensions.</p><h2>How to assess the evidence</h2><p>Review both the worker and the build-generated manifest logic. Fault tests should include changed bodies and changed response headers, not just missing files. The detailed development record distinguishes internal regressions from uncompleted phone-browser validation and independent review.</p><p><a href=\"https://github.com/Fablescateringandevents/v-security-suite/blob/main/web/sw.js\">Service worker</a> · <a href=\"https://github.com/Fablescateringandevents/v-security-suite/blob/main/scripts/assemble.mjs\">Manifest assembly</a> · <a href=\"https://github.com/Fablescateringandevents/v-security-suite/blob/main/docs/KEY-AND-DELIVERY-HARDENING-2026-10-23.md\">Recorded review and scope</a></p>"}, {"slug": "technical-cipher-qr-transport-boundaries", "title": "V Cipher: QR transport, message authentication and replay boundaries", "desc": "Why numbered QR frames need separate message authentication, how the two-phone roles differ, and why replay detection is session-scoped.", "tag": "Technical write-up · Protocol design", "body": "<p>By V · 23 October 2026. V Cipher 0.1.9 research is a separate experimental workflow from the ordinary VVault passphrase tool. Physical two-phone camera operation and independent review remain incomplete.</p><h2>Separate identity operations from transfer</h2><p>The Vault role holds identity keys and creates or opens messages. The Relay role moves public contact cards and encrypted bundles. The software asks for offline setup and isolation confirmation before Vault operations, but those are usability gates: they cannot prove an air gap or a trustworthy device.</p><h2>Two encryption layers and a signature</h2><p>The documented design wraps a fresh AES-256-GCM key using RSA-OAEP-3072 with SHA-256. ECDSA P-256 with SHA-256 signs the canonical VCMESSAGE2 envelope, including the sender, recipient and random message ID. Outer authenticated data binds the header. An inner passphrase-encrypted message additionally requires the conversation secret.</p><p>Identity fingerprints still need comparison through a trusted separate channel. A valid signature ties a message to the key being checked; it does not establish that an unverified contact card belongs to the intended person.</p><h2>QR checksums are not signatures</h2><p>The VCQR1 framing format includes a whole-transfer SHA-256 checksum, frame count, frame index and chunks of up to 360 base64 characters. Transfers are bounded to 96 frames and 24 KiB; messages are limited to 2,048 UTF-8 bytes. Frame collection expires after five minutes, with ordinary session locking clearing it sooner.</p><p>The checksum detects corruption or mixed frames. Anyone who can construct a transfer can compute a checksum, so it cannot authenticate a sender. The recipient Vault must still validate the encrypted message and signature after reassembly.</p><h2>Replay detection has a lifetime</h2><p>The replay tracker remembers at most 1,024 successful opens in one unlocked session. It resets on lock or reload. This catches repeated opens within that session; it is not durable replay prevention across sessions or devices. Random message IDs alone do not provide persistent replay history.</p><h2>No forward secrecy claim</h2><p>The design has no key ratchet. Long-term key compromise and captured historical bundles need to be considered alongside the independent conversation-secret layer. Multiple layers do not justify describing the system as impregnable.</p><h2>What the tests can establish</h2><p>Tests exercise envelope authentication, tampering, key/backup consistency, bounded QR reassembly and synthetic encoder/decoder interoperability. They cannot establish real-phone camera compatibility, OS-level isolation or the absence of cryptographic design flaws. Test only fictional messages and report security findings privately.</p><p><a href=\"https://github.com/Fablescateringandevents/v-security-suite/blob/main/apps/cipher/README.md\">Protocol and limits</a> · <a href=\"https://github.com/Fablescateringandevents/v-security-suite/blob/main/apps/cipher/protocol.js\">Protocol source</a> · <a href=\"https://github.com/Fablescateringandevents/v-security-suite/blob/main/apps/cipher/qr.js\">QR framing source</a></p>"}, {"slug": "development-log-key-and-offline-hardening", "title": "Development log 01: key handling and offline integrity", "desc": "What the latest internal review changed in key handling, offline responses and dependency checks—and what remains unverified.", "tag": "Development log · Internal review", "body": "<p>23 October 2026 · By V. This entry summarises the recorded internal development review for VVault/VRelay 0.2.9 and V Cipher 0.1.9 research. Development records and the live download are separate: check the version shown in the app and its release notes before testing.</p><h2>Reduce raw private-key export</h2><p>V Cipher’s active and restored identity keys now use non-extractable browser keys in the reviewed development source. Fresh creation prepares the encrypted backup before hardening and activating the identity. Tests cover export refusal, interoperability, cleanup and interrupted operations.</p><p>This reduces one export surface. It cannot stop compromised page code from using an available key, protect an already compromised device or guarantee browser memory erasure. Keep the original encrypted backup: active and restored sessions deliberately refuse re-export.</p><h2>Offline integrity includes response policy</h2><p>Checking file bytes alone does not verify the policy under which they run. The reviewed offline implementation pins canonical response headers alongside content hashes and reconstructs responses from that pinned policy. Missing policy metadata fails closed. The internal record reports 31 offline tests passing after the changes.</p><h2>Verify dependencies and native payloads</h2><p>The recorded checks compare retained QR dependency source and generated runtime files with their documented transformations. A separate clean compilation reproduced the VGuard candidate’s eight uncompressed APK payload entries using the specified toolchain. That does not mean the complete signed APK container was reproduced byte for byte, or that Android enforcement was tested.</p><h2>Evidence and remaining work</h2><p>The source record reports 240 Node tests passing for that review. This is an internal result, not an independent audit or a new test run performed for this article. Physical Android routing, phone-browser behaviour and two-phone camera operation remain open. V Cipher lacks forward secrecy and keeps replay history for one unlocked session.</p><p><a href=\"https://github.com/Fablescateringandevents/v-security-suite/blob/main/docs/KEY-AND-DELIVERY-HARDENING-2026-10-23.md\">Read the detailed source record</a> · <a href=\"/trust\">Current testing boundaries</a></p>"}, {"slug": "development-log-release-evidence", "title": "Development log 02: making release evidence easier to check", "desc": "Reviewed source archives, download consistency and honest build-verification scope in the experimental suite.", "tag": "Development log · Release engineering", "body": "<p>23 October 2026 · By V. This entry covers the recorded resource and release-integrity development pass: site 0.4.0, VVault/VRelay 0.2.6 and V Cipher 0.1.6 research. It describes that historical pass, not a claim that every current build has the same test count.</p><h2>Package only reviewed source paths</h2><p>The source archive process moved to an explicit reviewed file manifest. It rejects links, missing or unlisted paths and forbidden private/runtime file types before generating archives. The point is to make accidental file inclusion harder and the package contents easier to inspect.</p><p>A file allowlist cannot prove the text inside an approved file contains no secrets. Content review is still necessary. The internal record did not find an actual private-file leak in the project checkout.</p><h2>Bind downloadable bytes to the build report</h2><p>The artifact validator checks the embedded VGuard APK against its published report’s digest, length and artifact name. Fresh SDK checks were recorded separately from source-only checks. A signature establishes a signing identity for those bytes; it does not establish that the program is secure or works correctly on a phone.</p><h2>Bound work that cannot complete</h2><p>The recorded pass added one deadline for offline setup and guards against overlapping installation requests. It also refuses a full replay tracker before expensive cryptographic work begins. Browser background jobs may still complete after a page timeout; that distinction is documented rather than hidden.</p><h2>What was checked</h2><p>The historical record reports 166 Node tests passing, plus separate SDK verification and Python/Web Crypto interoperability checks. Those results have a defined scope. Actual Android routing and lifecycle behaviour, physical two-phone operation and independent review remained incomplete.</p><p><a href=\"https://github.com/Fablescateringandevents/v-security-suite/blob/main/docs/RESOURCE-AND-RELEASE-HARDENING-2026-10-23.md\">Read the full review and its limits</a> · <a href=\"/source\">Inspect source and release evidence</a></p>"}, {"slug": "development-log-next-validation-gates", "title": "Development log 03: the validation work still ahead", "desc": "The concrete device and independent-review gates we need before a wider launch, and how testers can help with harmless evidence.", "tag": "Development log · Next steps", "body": "<p>23 October 2026 · By V. The project is still an experimental beta. Publishing guides and passing internal tests do not complete its launch gates. This entry sets out the work still needed, without promising a release date.</p><h2>VGuard: prove behaviour on Android</h2><p>The first gate is a controlled comparison: the selected test app should lose fresh network access while an unselected app retains it, then regain access after stopping the firewall. Follow-up cases include DNS, IPv6, network changes, sleep, revocation and background lifecycle. Host stubs and parser tests do not substitute for the Android operating system.</p><h2>V Cipher: test the complete physical workflow</h2><p>Two real phones need to complete contact and message transfer, QR scanning, interruptions and recovery. A decoder handling synthetic images does not prove camera quality, permissions or device isolation. The protocol has no forward secrecy and replay history lasts one unlocked session; these remain explicit limits.</p><h2>Browser tools: check the browser and OS boundary</h2><p>Offline setup, clipboard handling, file saving, session clearing and recovery need practical checks on supported phone browsers. A clear interface cannot guarantee that an OS keyboard, extension or compromised endpoint leaves no copies.</p><h2>Independent scrutiny</h2><p>Internal adversarial testing is useful but is not independent review. A future review needs a defined source revision, scope, published findings where appropriate and evidence that fixes were retested. We have not completed an independent security audit.</p><h2>How to contribute a useful result</h2><p>Use synthetic messages and a spare test device. Record the app version, OS/browser version, exact steps and observed outcome. Do not include passwords, keys, private conversations or personal traffic logs. Submit ordinary test results through <a href=\"/feedback\">private feedback</a> and sensitive findings through <a href=\"/security\">the vulnerability reporting route</a>.</p><p><a href=\"/trust\">Read the current approach and limits</a> · <a href=\"/blog/android-firewall-test-checklist\">Start with the Android checklist</a></p>"}, {"slug": "test-local-message-encryption", "title": "How to test local message encryption with VVault", "desc": "A practical first VVault test: encrypt a fictional message, check the result and understand the limits of passphrase encryption.", "tag": "VVault · Practical guide", "body": "<p>Local encryption means the encryption operation happens on your device. It does not mean that the device, browser or code is automatically trustworthy. This guide is a small functional test of VVault, not proof that it is suitable for sensitive information.</p><h2>Start with a harmless message</h2><p>Open <a href=\"/apps/vault\">VVault</a> in a browser you control. Use a fictional sentence such as “Blue bicycle, test number 42”. Do not use a real password, address or private conversation as the sample. Read the current beta notice before continuing.</p><h2>Make a round trip</h2><ol><li>Choose the encryption operation and enter the fictional message.</li><li>Use a long, unique test passphrase. Do not reuse an account password.</li><li>Encrypt the message and save the resulting package before leaving the tab. The app clears its session when hidden or after inactivity.</li><li>Choose the unlock/decrypt operation, load the saved package and enter the same test passphrase.</li><li>Compare every character with your original sample, including spaces, punctuation and line breaks.</li></ol><h2>Check the failure path</h2><p>Using a copy of the package, try an incorrect passphrase. Unlocking should fail rather than show plausible plaintext. A failure message alone is not evidence of a security audit. If you see unexpected output, preserve only a fictional reproduction and report it through <a href=\"/feedback?product=VVault\">private feedback</a>.</p><h2>What this test cannot prove</h2><p>A successful round trip does not establish resistance to all attacks. VVault does not authenticate a sender, offer passphrase recovery or provide forward secrecy. Someone who later obtains the passphrase and an old package may be able to decrypt it. Malware, browser extensions, keyboards, screenshots and an unlocked device are outside the protection of message encryption.</p><h2>Before trying offline use</h2><p>Use the app’s offline option while connected, then disconnect and reload to check that it opens. Do not assume a page is available offline just because it was previously visited. Inspect the source and current release notes; independent review remains outstanding.</p>"}, {"slug": "transfer-ciphertext-without-sharing-the-passphrase", "title": "How to transfer ciphertext without sharing the passphrase", "desc": "Use VRelay to move a test VVault package, keep the passphrase separate and understand what a package-format check can and cannot tell you.", "tag": "VRelay · Practical guide", "body": "<p>An encrypted package and the passphrase that opens it serve different purposes. Putting both in the same message undermines their separation. VRelay helps copy, save or share a VVault package; it is not a hosted messaging service.</p><h2>Prepare the test package</h2><p>Create a package from fictional text in <a href=\"/apps/vault\">VVault</a>. Keep the test passphrase outside that package. Open <a href=\"/apps/relay\">VRelay</a> and paste the encrypted JSON or load its saved file. VRelay should never ask for the passphrase.</p><h2>Check and transfer</h2><ol><li>Select “Check package format”. Treat success as a structural check, not a sender identity check.</li><li>Copy the package, save it as a file or use the available share action.</li><li>Choose your transfer channel. The sharing app controls delivery and can see the ciphertext and its metadata.</li><li>Give the recipient the passphrase through a separately agreed channel. Sending a second message in the same compromised account is not meaningful separation.</li><li>Ask the recipient to unlock the fictional message in VVault and compare the result.</li></ol><h2>What the check means</h2><p>VRelay validates the envelope structure. It does not decrypt the message, authenticate the sender, inspect the plaintext or establish that the contents are safe. There is no delivery receipt or hosted relay in this release.</p><h2>Metadata still matters</h2><p>Encryption does not hide everything. A provider may still observe who exchanged a file, when it was sent and its approximate size. A filename or accompanying message may disclose context. Avoid descriptive personal filenames even in test workflows.</p><h2>Keep a usable copy before switching apps</h2><p>The page clears its session when hidden or after inactivity. Save or copy the package before switching away. Clearing the page does not erase files, clipboard history, backups or copies stored by another application.</p><p>These tools are early and unaudited. Use synthetic data only. Read <a href=\"/trust\">the current testing limits</a> and report reproducible problems without including real secrets.</p>"}, {"slug": "android-firewall-test-checklist", "title": "An Android app-firewall test checklist for VGuard", "desc": "Compare selected and unselected apps, check recovery and record useful VGuard test results without treating a preview as verified protection.", "tag": "VGuard · Test checklist", "body": "<p>VGuard is an experimental Android local-VPN firewall candidate. Its intended behaviour is to discard packets from selected apps while other apps retain their connection. Live Android enforcement remains unverified. This checklist helps testers collect evidence on a spare device; it is not a recommendation to rely on the preview.</p><h2>Understand the Android VPN slot</h2><p>A local-VPN firewall is different from a remote VPN service. VGuard uses Android’s VPN interface locally and may replace another VPN. It does not provide the remote provider’s IP masking. Do not conduct this test during sensitive activity or while depending on another VPN connection.</p><h2>Run a comparison</h2><ol><li>Read the <a href=\"/apps/guard\">candidate download and setup notes</a>. Record the app version and Android version.</li><li>With VGuard stopped, confirm two independent test apps can make fresh network requests. Cached content is not a useful connectivity test.</li><li>Select only one app for blocking. Start VGuard and approve the Android VPN request yourself.</li><li>Repeat fresh requests in both apps. Record whether the selected app fails while the unselected app still connects.</li><li>Stop VGuard and check that the selected app can connect again.</li></ol><h2>Test state changes separately</h2><p>If the basic comparison works, record what happens after screen lock, sleep, Wi-Fi/mobile changes and VPN revocation. Keep each case separate. A single successful request test does not establish DNS, IPv6, background or bypass behaviour.</p><h2>Know what it does not control</h2><p>VGuard does not disable camera, microphone or location permissions, detect all spyware or prevent an app collecting information while offline. An app may store data and send it after access returns. This candidate has no always-on mode, lockdown or automatic restart.</p><h2>Write a useful report</h2><p>Include version numbers, the harmless test apps used, the steps, expected result and actual result. Do not attach personal traffic logs or real account details. Submit the result through <a href=\"/feedback?product=VGuard\">private tester feedback</a>. Host tests and signature checks are different from real-device routing evidence; both must be described honestly.</p>"}, {"slug": "read-security-claims-before-testing", "title": "How to read security claims before testing a privacy app", "desc": "Distinguish open source, automated tests, real-device checks and independent audits before deciding what a privacy tool can be trusted to do.", "tag": "Privacy basics · Evaluation", "body": "<p>A privacy tool should explain its boundaries as clearly as its features. Before trying one, identify what you want to protect, from whom, and what happens if the tool fails. For an experimental project, start with fictional data and a limited question.</p><h2>Ask what the tool actually protects</h2><p>Message encryption protects a particular message representation. A network filter changes which connections can pass. Neither automatically protects a compromised endpoint, hides all metadata or replaces safe device access. Define the task before comparing products.</p><h2>Separate four kinds of evidence</h2><ul><li><strong>Public source:</strong> enables inspection; it does not mean someone qualified has reviewed every line.</li><li><strong>Automated tests:</strong> check specified cases under stated conditions; they cannot establish the absence of unknown vulnerabilities.</li><li><strong>Real-device tests:</strong> show outcomes on particular devices and versions, not every operating system or configuration.</li><li><strong>Independent audit:</strong> needs a named scope, date, findings and remediation status. An internal review is not independent.</li></ul><h2>Look for failure behaviour</h2><p>Ask what happens when a password is wrong, a package is malformed, a connection fails or an app is interrupted. A safe failure should be understandable. Also ask whether old data remains in files, clipboard history or backups after the interface clears.</p><h2>Read the current limits</h2><p>For Vellivex, <a href=\"/trust\">Our approach</a> separates internal checks from outstanding real-phone validation and independent review. VVault has no sender authentication, recovery or forward secrecy. VRelay does not deliver messages through a hosted service. VGuard’s live blocking and V Cipher’s physical two-phone workflow remain unverified.</p><h2>Make feedback reproducible</h2><p>Use a minimal fictional example, record the version and steps, and state what you expected. Keep vulnerability details private through <a href=\"/security\">the reporting route</a>. Do not send real keys or private messages as evidence. Good evidence improves a project; absolute claims such as “impregnable” do not.</p>"}];
function blogIndex(){return layout('Privacy guides & field notes',head('V / GUIDES & FIELD NOTES','Understand the tools.<br><em>Test the boundaries.</em>','Practical guides and development logs for curious testers. Clear steps, recorded changes and visible limits.')+`<div class="wrap content">${experimental}<section class="products">${blogPosts.map(p=>`<article class="product"><span class="tag">${p.tag}</span><h2 style="font-size:1.7rem"><a href="/blog/${p.slug}">${p.title}</a></h2><p>${p.desc}</p><p class="fine">V · 23 October 2026</p><a class="text-link" href="/blog/${p.slug}">Read the post ↗</a></article>`).join('')}</section><p class="fine">Guides describe the experimental release at publication. Check each tool’s current status before testing.</p></div>`,{indexable:true,canonical:'/blog',description:'Vellivex guides and development logs: local encryption, ciphertext transfer, Android testing, release evidence and open validation gates.'});}
function blogArticle(slug){const p=blogPosts.find(p=>p.slug===slug);if(!p)return;return layout(p.title,head(p.tag,p.title,p.desc)+`<article class="wrap narrow content"><p class="fine">By V · Published 23 October 2026 · Experimental project notes</p>${experimental}<div class="guide-body">${p.body}</div><hr><p><a href="/blog">← All guides</a> · <a href="/feedback">Share test feedback ↗</a></p><h2>Keep exploring</h2><ul>${blogPosts.filter(x=>x!==p).map(x=>`<li><a href="/blog/${x.slug}">${x.title}</a></li>`).join('')}</ul></article>`,{indexable:true,canonical:'/blog/'+p.slug,description:p.desc});}
export const blogPaths=()=>['/blog',...blogPosts.map(p=>'/blog/'+p.slug)];

function testingPage(){
 const tasks=[['VVault','vault','Encrypt, then unlock','Use fictional text and a fresh test passphrase. Encrypt it, save the package, switch to unlock and compare the recovered text. Try a wrong passphrase: it should fail without showing plaintext.','/blog/test-local-message-encryption'],['VRelay','relay','Check and transfer a package','Paste a fictional VVault package and check its format. Copy or save it, then unlock the copy in VVault. Never enter a passphrase in VRelay. A format check does not authenticate a sender or verify the contents.','/blog/transfer-ciphertext-without-sharing-the-passphrase'],['VGuard','guard','Compare two harmless apps','On a spare Android device, follow the candidate setup notes. Confirm fresh requests work in two test apps, select only one for blocking, compare both, then stop VGuard and check recovery. Live enforcement remains unverified. This can replace an existing VPN.','/blog/android-firewall-test-checklist'],['V Cipher','cipher','Explore the research workflow','Read the two-phone setup and limits before attempting a fictional exchange. Record device models, OS/browser versions, camera permissions and which QR step succeeds or fails. Physical two-phone camera and OS behaviour remain unverified. No forward secrecy; replay tracking lasts one unlocked session.','/blog/technical-cipher-qr-transport-boundaries']];
 const demos=[['vault-encrypt','Encrypt fictional text','The input contains “Blue bicycle, test number 42. Fictional demo only.” After Encrypt on this device, VVault shows an encrypted package and confirms local encryption.'],['vault-unlock','Unlock the test package','Switch to Unlock an encrypted package, paste the saved package and enter the same demo passphrase. VVault recovers the original fictional text and clears the passphrase field.'],['relay-check','Check the package format','Paste the encrypted package into VRelay and select Check package format. The result confirms structure only; it does not authenticate the sender or verify encrypted contents.']];
 return layout('Start testing',head('V / TESTER START HERE','One small test.<br><em>One useful result.</em>','Choose a tool, use fictional data and tell us what happened. A failed test is useful evidence too.')+`<div class="wrap content">${experimental}<p>No independent security audit has been completed. Do not use real secrets or rely on these releases for sensitive activity.</p><section><h2>Choose your task</h2><div class="products">${tasks.map(([name,slug,title,body,guide])=>`<article class="product"><span class="tag">${name}</span><h3>${title}</h3><p>${body}</p><div class="actions"><a class="button small" href="/apps/${slug}">Open ${name}</a><a class="text-link" href="${guide}">Read the steps ↗</a></div><p><a href="/feedback?product=${encodeURIComponent(name==='V Cipher'?'VCipher':name)}&kind=test">Report this test ↗</a></p></article>`).join('')}</div></section><section class="section"><h2>See the browser steps</h2><p>Three silent, six-second walkthroughs made from still frames captured during successful live browser tests on 23 October 2026. All message content and the demonstration passphrase are fictional. These show browser behaviour, not Android or two-phone validation.</p><div class="demo-grid">${demos.map(([slug,title,transcript])=>`<article class="panel"><h3>${title}</h3><video class="test-demo" controls preload="none" aria-label="${title}"><source src="/demos/${slug}.mp4" type="video/mp4"><a href="/demos/${slug}.mp4">Download the walkthrough</a></video><details><summary>Read the walkthrough</summary><p>${transcript}</p></details></article>`).join('')}</div></section><section class="panel"><h2>Make your report reproducible</h2><ol><li>Choose the product and “Device test result” in the feedback form.</li><li>Include app version, device, OS and browser version.</li><li>Write the task, exact steps, expected result and actual result. State pass, fail or blocked.</li><li>Keep the confirmation reference so you can identify the result later.</li></ol><p>Use synthetic examples only. Do not include private messages, keys, passphrases, account details or personal traffic logs. Reports are stored privately; do not assume they are anonymous. For vulnerability details, use the <a href="/security">security reporting route</a>.</p><a class="button" href="/feedback?kind=test">Send a test result ↗</a></section><p><a href="/blog">Read the guides and technical notes ↗</a></p></div>`,{indexable:true,canonical:'/testing',description:'Start testing Vellivex with fictional data: four focused tasks, three captured browser walkthroughs and private test feedback.'});
}
